// One dismiss policy for every overlay in the app (TASK-81), because seven per-overlay patches
// drift apart. Escape always closes and focus always returns to whatever opened the overlay.
//   'menu'  also closes on an outside click. The returned ref MUST wrap trigger + panel: with the
//           ref on the panel alone, clicking the trigger closes here and the trigger's own toggle
//           immediately reopens it.
//   'modal' pulls focus into the panel on open, so a keyboard user lands inside the dialog they
//           just opened. Backdrop clicks stay each modal's own business (some guard on in-flight work).
//   'panel' is Escape-only, for overlays rendered twice (mobile card + desktop table) or portalled
//           away from the trigger, where one container ref cannot answer "was this click inside?".
// The outside-click listener is capture-phase `click`, not `mousedown`: by click time the browser
// has already moved focus, so an input that saves onBlur has saved before the overlay unmounts,
// and capture still sees clicks inside subtrees that stopPropagation (the job table does, a lot).
function useDismiss(open:boolean,close:()=>void,kind:'menu'|'modal'|'panel'='menu'){const ref=useRef<any>(null);const opener=useRef<any>(null);const onClose=useRef(close);onClose.current=close;useEffect(()=>{if(!open)return;opener.current=document.activeElement;if(kind==='modal'&&ref.current&&!ref.current.contains(document.activeElement))ref.current.focus?.();const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose.current()};const onClick=(e:MouseEvent)=>{if(kind==='menu'&&ref.current&&!ref.current.contains(e.target as Node))onClose.current()};document.addEventListener('keydown',onKey);document.addEventListener('click',onClick,true);return()=>{document.removeEventListener('keydown',onKey);document.removeEventListener('click',onClick,true);const trigger=opener.current;if(trigger?.focus&&document.contains(trigger)&&(!document.activeElement||document.activeElement===document.body))trigger.focus()}},[open,kind]);return ref}

function Badge({children,tone='slate',title,...rest}:{children:any;tone?:string;title?:string;[key:string]:any}){const tones:any={green:'app-badge-green',red:'app-badge-red',yellow:'app-badge-yellow',blue:'app-badge-blue',purple:'app-badge-purple',slate:'app-badge-slate'};return <span title={title} {...rest} className={(tones[tone]||tones.slate)+' app-badge inline-flex max-w-full rounded-full px-2 py-0.5 text-[11px] font-semibold tracking-tight break-words'}>{children||'—'}</span>}
function displayJobTitle(value?:string|null){const text=(value||'').replace(/\s*[-–—,;:]*\s*\(?\s*[mwfdx](?:\s*\/\s*[mwfdx]){1,3}\s*\)?\s*$/i,'').replace(/\s+/g,' ').trim();return text||value||'—'}
function cleanDisplayLocation(value?:string|null){let text=(value||'').replace(/\s+/g,' ').trim();if(!text)return '';const cityMap:[[string,RegExp],...Array<[string,RegExp]>]=[['Vienna',/\b(?:vienna|wien)\b/i],['Berlin',/\bberlin\b/i],['Munich',/\b(?:munich|münchen|muenchen)\b/i],['Graz',/\bgraz\b/i],['Linz',/\blinz\b/i],['Salzburg',/\bsalzburg\b/i],['Zurich',/\b(?:zurich|zürich|zuerich)\b/i],['Budapest',/\bbudapest\b/i]];for(const [city,re] of cityMap){if(re.test(text))return city}return text.replace(/\b(?:AUT|AT|DEU|DE|CHE|CH|HUN|HU)\b/gi,' ').replace(/\b\d{3,6}\b/g,' ').replace(/\b(?:Austria|Österreich|Germany|Deutschland|Switzerland|Schweiz|Hungary)\b/gi,' ').split(/[,;/|]/)[0].replace(/\s+/g,' ').trim()||text}
function locationLabel(value?:string|null){const title=cleanDisplayLocation(value);if(!title)return {label:'—',title:''};return {label:title,title:(value||'').trim()}}
function locationLabels(value?:string|null){const raw=(value||'').trim();if(!raw)return [locationLabel(raw)];const parts=raw.split(/\s*(?:[,;]|\s+\/\s+)\s*/).map(x=>x.trim()).filter(Boolean).filter(x=>! /^(at|austria|österreich|aut|\d{3,6})$/i.test(x));const items=(parts.length?parts:[raw]).map(locationLabel).filter(x=>x.label&&x.label!=='—');const seen=new Set<string>();return items.filter(x=>{const key=x.label.toLowerCase();if(seen.has(key))return false;seen.add(key);return true})}
function LocationBadges({value,tones={},onToggle}:{value?:string|null;tones?:Record<string,string>;onToggle?:(label:string)=>void}){const labels=locationLabels(value);return <>{labels.length?labels.map((loc,i)=><button key={i} type="button" title={loc.title||'Click to cycle badge color'} onClick={e=>{e.stopPropagation();onToggle?.(loc.label)}} className="bg-transparent p-0"><Badge tone={tones[loc.label]||'slate'} title={loc.title}>{loc.label}</Badge></button>):null}</>}
function workModeLabel(mode?:string|null){return mode&&mode!=='unknown'?mode:''}
const statusTone=(s:string)=>({to_apply:'blue',applied:'purple',interview:'green',offer:'green',accepted:'green',rejected:'red',withdrawn:'slate',skipped:'yellow',archived:'slate'} as any)[s]||'slate';
const priorityTone=(p?:string)=>p==='high'?'red':p==='medium'?'yellow':p==='low'?'slate':'slate';
