function hrefFor(raw?:string){let v=(raw||'').trim(); if(!v)return ''; if(v.startsWith('http://')||v.startsWith('https://'))return v; if(v.startsWith('https-')||v.startsWith('http-')){const [scheme,...rest]=v.split('-'); const host=rest.shift(); if(host&&host.includes('.'))return `${scheme}://${host}/${rest.join('/')}`} if(v.includes('.')&&!v.includes(' '))return 'https://'+v; return v}
function dashboardCompany(j:Job){const c=(j.company||'').trim();return (!c||/^unknown company$/i.test(c))&&!j.latest_evaluation?'Imported link':(c||'Unknown company')}
function addedByRaw(j:Job){return (j.submitted_for_username&&j.created_by_username)||j.submitted_by||''}
function addedByTitle(j:Job){return (j.submitted_for_username&&(j.created_by_email||j.created_by_username))||j.submitted_by||''}
function personNameParts(raw?:string|null){const text=(raw||'').trim();if(!text)return [];return (text.includes('@')?text.split('@')[0].split('+')[0]:text).replace(/[._-]+/g,' ').replace(/\s+/g,' ').trim().split(' ').filter(Boolean)}
function displayPersonName(raw?:string|null,disambiguate=false){const text=(raw||'').trim();const parts=personNameParts(raw);const first=parts[0]?parts[0][0].toUpperCase()+parts[0].slice(1):'';return disambiguate&&parts[1]?`${first} ${parts[1][0].toUpperCase()}.`:first||text}
function AddedByBadge({job,disambiguate=false}:{job:Job;disambiguate?:boolean}){const raw=addedByRaw(job);return raw?<Badge title={addedByTitle(job)}>{displayPersonName(raw,disambiguate)}</Badge>:null}
function daysSince(date?:string|null){if(!date)return null; return Math.floor((Date.now()-new Date(date+'T00:00:00').getTime())/86400000)}
// Every board urgency threshold has exactly one home: JobLead.STALE_APPLIED_DAYS and friends in
// backend/jobradar/models.py, shipped to the client by /api/auth/me/ as board_thresholds. There is
// deliberately no numeric fallback here - a second copy of "21" in this file is the bug TASK-96
// exists to delete - so every read below tolerates an absent number instead of guessing one.
// cachedAuthUser() is read first because it is this page load's live /auth/me/ response: RequireAuth
// resolves it before any of these callers render, so a localStorage copy written before this deploy
// (which has no board_thresholds key) can never be the value we badge from.
const boardThresholdDefaults:{stale_applied_days?:number;stale_unapplied_days?:number;deadline_soon_days?:number;unapplied_statuses:string[];actionable_statuses:string[]}={unapplied_statuses:['new','reviewed','to_apply'],actionable_statuses:mailboxActionableJobStatuses};
function boardThresholds(){return {...boardThresholdDefaults,...(cachedAuthUser()?.board_thresholds||storedUser()?.board_thresholds||{})}}
function isStaleStatus(j:Job){const t=boardThresholds().stale_applied_days;const d=daysSince(j.status_date); return lastUpdateStatuses.includes(j.status)&&d!==null&&t!==undefined&&d>t}
function isStaleUnapplied(j:Job){const t=boardThresholds();const d=daysSince((j.created_at||'').slice(0,10)); return t.unapplied_statuses.includes(j.status)&&d!==null&&t.stale_unapplied_days!==undefined&&d>t.stale_unapplied_days}
function interviewWhen(iso?:string|null){if(!iso)return '';const d=new Date(iso);return isNaN(d.getTime())?'':d.toLocaleString(undefined,{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}
function UrgencyBadges({job,className='mt-0.5 flex flex-wrap gap-1'}:{job:Job;className?:string}){const t=boardThresholds();if(!t.unapplied_statuses.includes(job.status))return null;const deadline=t.deadline_soon_days===undefined?null:deadlineBadge(daysUntil(job.apply_by),t.deadline_soon_days);const stale=isStaleUnapplied(job);if(!deadline&&!stale)return null;return <div className={className}>{deadline&&<Badge tone={deadline.tone} title={`Apply by ${job.apply_by}`}>{deadline.label}</Badge>}{stale&&<Badge tone="slate" title={`Added ${daysSince((job.created_at||'').slice(0,10))} days ago and never applied to; stale after ${t.stale_unapplied_days} days`}>Stale lead</Badge>}</div>}
function statusNeedsDate(s?:string){return datedStatuses.includes(s||'')}
function statusHasLastUpdate(s?:string){return lastUpdateStatuses.includes(s||'')}
function addDays(date:string,days:number){const d=new Date(date+'T00:00:00');d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function daysUntil(date?:string|null){if(!date)return null; return Math.ceil((new Date(date+'T00:00:00').getTime()-Date.now())/86400000)}
function feedbackDays(j:Job){if(j.feedback_due_date)return daysUntil(j.feedback_due_date); const t=boardThresholds().stale_applied_days;const d=daysSince(j.status_date); return (j.status==='applied'||j.status==='interview')&&d!==null&&t!==undefined?t-d:null}
function FeedbackDueText({days,prefix=false}:{days:number|null;prefix?:boolean}){if(days===null)return <>{prefix?'Feedback ':''}—</>; if(days<0)return <span className="feedback-overdue">{prefix&&<span className="leading-none">Feedback</span>}<span className="leading-none">{Math.abs(days)}d</span><span className="leading-none">overdue</span></span>; return <>{prefix?'Feedback ':''}{days}d left</>}
function ApplicationPace({stats}:{stats:any}){const monthWeeks=Array.isArray(stats.month_week_applications)?stats.month_week_applications:[];const workdays=Array.isArray(stats.workday_applications)?stats.workday_applications:[];const weekMax=Math.max(1,...monthWeeks.map((w:any)=>Number(w.count)||0));const dayMax=Math.max(1,...workdays.map((d:any)=>Number(d.count)||0));const countLabel=(n:any)=>`${Number(n)||0} application${Number(n)===1?'':'s'}`;return <div className="premium-card p-4"><div className="mb-3 flex items-start justify-between gap-3"><div><div className="text-xs uppercase text-slate-500">Application pace</div><div className="text-2xl font-semibold">{stats.applications_this_week??0}<span className="ml-1 text-sm font-medium text-slate-500">this week</span></div></div><div className="text-right"><div className="text-xs uppercase text-slate-500">Per workday</div><div className="text-2xl font-semibold">{stats.applications_per_workday??0}</div></div></div>{monthWeeks.length>0&&<div className="mb-4"><div className="mb-1 text-[10px] font-semibold uppercase text-slate-500">Weeks this month</div><div className="grid gap-2" style={{gridTemplateColumns:`repeat(${monthWeeks.length},minmax(0,1fr))`}}>{monthWeeks.map((w:any)=><div key={w.start||w.label} className="min-w-0" title={`${w.label} (${w.range}): ${countLabel(w.count)}`}><div className="flex h-16 items-end"><div className="w-full rounded-t-lg bg-blue-500/80 shadow-sm" style={{height:`${Math.max(8,(Number(w.count)||0)/weekMax*100)}%`}}/></div><div className="mt-1 min-h-8 text-center leading-tight"><div className="truncate text-[10px] font-semibold text-slate-600">{w.label}</div><div className="truncate text-[10px] font-medium text-slate-500">{w.range}</div></div></div>)}</div></div>}{workdays.length>0&&<div><div className="mb-1 text-[10px] font-semibold uppercase text-slate-500">Month by workday</div><div className="overflow-x-auto"><div className="grid h-20 items-end gap-1" style={{gridTemplateColumns:`repeat(${workdays.length},minmax(8px,1fr))`}}>{workdays.map((d:any)=><div key={d.date||d.label} className="flex h-full min-w-0 flex-col justify-end gap-1" title={`${d.date||d.label}: ${countLabel(d.count)}`}><div className="rounded-t-md bg-blue-500/80 shadow-sm" style={{height:`${Math.max(8,(Number(d.count)||0)/dayMax*100)}%`}}/><div className="truncate text-center text-[9px] font-medium text-slate-500">{d.label}</div></div>)}</div></div></div>}</div>}
// TASK-85 AC3. "Reached interview/offer" is the journey over the applied_at cohort, not the current
