function FunnelCohort({label,c}:{label:string;c:FunnelCounts}){return <div className="min-w-0"><div className="mb-1 text-[10px] font-semibold uppercase text-slate-500">{label}</div><div className="grid grid-cols-3 gap-2 text-center">{([['Applications',c.applications],['Reached interview',c.interviews],['Reached offer',c.offers]] as [string,number][]).map(([t,n])=><div key={t} className="rounded-xl border border-slate-200 p-2 dark:border-white/10"><div className="text-xl font-semibold">{n}</div><div className="text-[10px] uppercase leading-tight text-slate-500">{t}</div></div>)}</div><div className="mt-2 grid gap-1 text-[11px] text-slate-600 sm:grid-cols-2 dark:text-slate-300"><div>Applied → interview: <b>{ratePercent(c.applied_to_interview_rate)}</b></div><div>Interview → offer: <b>{ratePercent(c.interview_to_offer_rate)}</b></div></div></div>}
function FunnelPanel({stats}:{stats:Stats}){const funnel=stats.funnel;if(!funnel)return <div className="premium-card p-4"><div className="text-xs uppercase text-slate-500">Conversion funnel</div><div className="mt-1 text-sm text-slate-500">No conversion data yet.</div></div>;const orphans=funnel.interviews_without_application||0;return <div className="premium-card p-4"><div className="mb-3 text-xs uppercase text-slate-500">Conversion funnel</div><div className="grid gap-4 md:grid-cols-2"><FunnelCohort label="All time" c={funnel.all_time}/><FunnelCohort label={`Last ${funnel.recent_window_days} days (since ${funnel.recent_window_start})`} c={funnel.recent}/></div>{orphans>0&&<p className="mt-3 rounded-xl bg-amber-50 px-3 py-2 text-[11px] text-amber-900 dark:bg-amber-400/10 dark:text-amber-100">{orphans} job{orphans===1?'':'s'} reached interview with no application date, so {orphans===1?'it is':'they are'} left out of these rates. Set an application date on {orphans===1?'it':'them'} to count {orphans===1?'it':'them'} in.</p>}</div>}
function SourcePanel({stats}:{stats:Stats}){const rows=stats.source_effectiveness||[];return <div className="premium-card p-4"><div className="mb-2 text-xs uppercase text-slate-500">Source effectiveness</div>{rows.length?<div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead className="text-[10px] uppercase text-slate-500"><tr><th scope="col" className="py-1 pr-2 font-medium">Source</th><th scope="col" className="py-1 pr-2 text-right font-medium">Applications</th><th scope="col" className="py-1 pr-2 text-right font-medium">Reached interview</th><th scope="col" className="py-1 text-right font-medium">Interview rate</th></tr></thead><tbody>{rows.map(r=><tr key={r.source} className="border-t border-slate-200 dark:border-white/10"><th scope="row" className="break-words py-1 pr-2 font-medium">{sourceLabel(r.source)}</th><td className="py-1 pr-2 text-right">{r.applications}</td><td className="py-1 pr-2 text-right">{r.interviews}</td><td className="py-1 text-right font-semibold">{ratePercent(r.interview_rate)}</td></tr>)}</tbody></table></div>:<div className="text-sm text-slate-500">No applications yet, so there is nothing to compare.</div>}</div>}
// mailbox_review is FIRST here on purpose (TASK-117 AC3): a fresh panelOrder with no saved
