const dashboardPanelLabels:Record<string,string>={mailbox_review:'Email decisions',feedback_due:'Feedback deadlines',total:'Total',new_high_priority:'New high priority',active_applied:'Active applied',active_interviews:'Active interviews',due_followups:'Due follow-ups',upcoming_interviews:'Upcoming interviews',application_pace:'Application pace',funnel:'Conversion funnel',source_effectiveness:'Source effectiveness',mailbox_unmatched:'Unmatched mail'};
const dashboardPanelOrderKey='dachapply_dashboard_panel_order';
const dashboardPanelHiddenKey='dachapply_dashboard_panel_hidden';
// TASK-174 AC2/AC5. Attaching mail to a job is a batched maintenance chore, so its panel is off
// until the owner asks for it - a default, never a removal: it is still listed in the Panels menu
// and one click turns it on (AC3).
// dashboardPanelHiddenKey records only the HIDDEN set, so "never chose" and "deliberately chose to
// show" are the same absence and a default applied on every load would silently re-hide a panel the
// owner had switched on. This second key is the distinction: it lists the ids whose default has
// already been applied once. Not in it -> the owner never chose -> apply the default and record it.
// In it -> whatever the hidden set says is the owner's own decision -> never touched again.
// The rule itself is applyDefaultHiddenPanels in appUtils.ts, pure and unit-tested; this file only
// does the two localStorage reads and writes around it.
const dashboardPanelDefaultsSeededKey='dachapply_dashboard_panel_defaults_seeded';
const dashboardPanelDefaultHidden=['mailbox_unmatched'];
// TASK-181. The per-panel ⋮ menu and the hover-only cluster it fronted are both GONE from here.
// TASK-102's finding still holds and is the reason this removal is not just a deletion: `hidden
// group-hover:flex` took the hover buttons out of the tab order entirely (display:none), and HTML5
// drag-and-drop never fires on touch - so a panel that can only be rearranged by dragging it cannot
// be rearranged by keyboard or on a phone at all. Move left / Move right / Hide therefore moved UP,
// into the board's Panels menu (see the panel rows in Dashboard's render), which is a real tab stop
// per panel. What is left here is the pointer path: drag a panel onto another to reorder, or onto
// the drop zone Dashboard shows during a drag to hide it.
// TASK-183 adds the feedback that gesture had none of. `held` dims the panel the owner is holding
// so it stays identifiable once the grid starts moving around it (AC6); `landing` marks the slot it
// will occupy on release, with a dashed blue outline and a "Drops here" badge. Both are driven by
// Dashboard's preview state, and `landing` is off whenever the previewed order matches the saved one
// - dropping a panel back where it started must not claim a move it is not going to make (AC5).
// Exported for appPanels.test.tsx, which counts the removed buttons in the rendered markup.
export function DashboardPanel({id,wide=false,children,onDragStart,onDrop,onDragOver,onDragEnd,held=false,landing=false}:{id:string;wide?:boolean;children:any;onDragStart:()=>void;onDrop:()=>void;onDragOver:(e:any)=>void;onDragEnd:()=>void;held?:boolean;landing?:boolean}){const panelRef=useRef<HTMLDivElement|null>(null);
// TASK-134: the whole panel is draggable, so a drag starting on message text is claimed by the
// panel and selects nothing. Chrome picks drag-vs-select at the first mousemove, so preventing
// dragstart is already too late; the attribute must be off before then. Imperative on purpose --
// a setState here is async and may not land before that decision.
const allowDrag=(on:boolean)=>panelRef.current?.setAttribute('draggable',on?'true':'false');
return <div ref={panelRef} draggable data-panel={id} onMouseDown={e=>allowDrag(!(e.target as HTMLElement).closest?.('.mailbox-selectable'))} onMouseUp={()=>allowDrag(true)} onDragStart={onDragStart} onDrop={onDrop} onDragOver={onDragOver} onDragEnd={onDragEnd} className={(wide?'dashboard-panel-wide md:col-span-5 md:row-span-1 ':'premium-card dashboard-panel-small p-4 md:col-span-1 md:row-span-1 ')+(held?'opacity-60 ':'')+(landing?'rounded-2xl outline outline-2 outline-dashed outline-blue-500 outline-offset-2 ':'')+'relative cursor-move'}>{landing&&<span className="pointer-events-none absolute -top-2 left-1/2 z-10 -translate-x-1/2 whitespace-nowrap rounded-full bg-blue-600 px-2 py-0.5 text-[10px] font-semibold text-white shadow-lg">Drops here</span>}{children}</div>}
