const anon=publicMode&&!storedUser();const[form,setForm]=useState<any>(()=>prefill||JSON.parse(localStorage.getItem(draftKey)||'null')||(publicMode?{...empty,submitted_by:'',submitter_reason:''}:empty));function set(v:any){setForm(v);localStorage.setItem(draftKey,JSON.stringify(v))}useEffect(()=>{if(prefill){setForm(prefill);localStorage.setItem(draftKey,JSON.stringify(prefill))}},[loc.search,loc.hash]);const[summary,setSummary]=useState<any>(null);const[err,setErr]=useState<any>(()=>JSON.parse(localStorage.getItem(draftKey+'_err')||'null'));const[duplicateActions,setDuplicateActions]=useState<any[]>(()=>JSON.parse(localStorage.getItem(draftKey+'_actions')||'[]'));const[loading,setLoading]=useState(false);const[promptLoading,setPromptLoading]=useState(false);const[quickPrompt,setQuickPrompt]=useState('');const[quickPromptCopied,setQuickPromptCopied]=useState(false);const[quickPromptCopyFailed,setQuickPromptCopyFailed]=useState(false);const[advanced,setAdvanced]=useState(!publicMode);const linkDraftRef=useRef((form.url||'')+'\n'+(form.raw_description||''));useEffect(()=>{const now=(form.url||'')+'\n'+(form.raw_description||'');if(now!==linkDraftRef.current){linkDraftRef.current=now;setErr(null);setDuplicateActions([]);localStorage.removeItem(draftKey+'_err');localStorage.removeItem(draftKey+'_actions')}},[form.url,form.raw_description]);useEffect(()=>{err?localStorage.setItem(draftKey+'_err',JSON.stringify(err)):localStorage.removeItem(draftKey+'_err')},[err]);useEffect(()=>{duplicateActions.length?localStorage.setItem(draftKey+'_actions',JSON.stringify(duplicateActions)):localStorage.removeItem(draftKey+'_actions')},[duplicateActions]);
