  return <li className={(m.sent_by_owner?'border-blue-200 bg-blue-50/40 dark:border-blue-500/30 dark:bg-blue-500/5 ':'')+'min-w-0 rounded-lg border border-slate-100 p-2 text-xs dark:border-white/10'}><div className="flex min-w-0 items-center justify-between gap-2"><span className="min-w-0 truncate font-medium text-slate-700 dark:text-slate-200">{decodeHtmlEntities(m.subject)||'(no subject)'}</span><span className="flex shrink-0 items-center gap-1.5"><Badge tone="slate">{threadLabel}</Badge>{m.classification==='uncertain'&&<Badge tone="yellow">Uncertain</Badge>}{m.gmail_url&&<a href={m.gmail_url} target="_blank" rel="noreferrer" className="btn-muted px-1.5 py-0.5 text-[10px]">Reply in Gmail ↗</a>}<MailboxReplyControl m={m}/></span></div><div className="mt-0.5 flex min-w-0 items-center justify-between gap-2 text-slate-500"><span className="min-w-0 truncate">{m.sent_by_owner?'You':m.sender} · {m.received_at?new Date(m.received_at).toLocaleString():'received date unknown'}</span>{hasBody&&<button type="button" className="btn-muted shrink-0 px-1.5 py-0.5 text-[10px]" aria-expanded={expanded} aria-controls={bodyId} onClick={()=>setExpanded(x=>!x)}>{expanded?'Hide message ▾':'Read message ▸'}</button>}</div>{expanded&&hasBody&&<div id={bodyId} className="mt-1.5 min-w-0 max-h-48 overflow-y-auto whitespace-pre-wrap break-words rounded-lg bg-slate-50 p-2 text-slate-600 dark:bg-white/5 dark:text-slate-300">{decodeHtmlEntities(m.body_text)}</div>}<MailboxCalendarInvite m={m}/><MailboxAttachmentList m={m}/></li>
